import numpy as np
from scipy.optimize import minimize
import sys

def construct_packing():
    """
    Runs an SLSQP optimization where the consensus contacts are enforced
    as equality constraints.
    """
    N = 26

    def pack_to_z(c, r):
        z = np.zeros(N*3); z[0::3], z[1::3], z[2::3] = c[:,0], c[:,1], r; return z
    def z_to_pack(z):
        c = np.vstack((z[0::3], z[1::3])).T; r = z[2::3]; return c, r
    def objective(z): return -np.sum(z[2::3])

    # Load the consensus graph
    try:
        consensus_boundary = np.loadtxt("storage/Aletheia/consensus/boundary_3way_consensus.txt", delimiter=',', dtype=str)
        consensus_pairs = np.loadtxt("storage/Aletheia/consensus/pairs_3way_consensus.txt", dtype=int)
    except IOError:
        print("ERROR: Could not load consensus graph files.", file=sys.stderr)
        return np.zeros((N,2)), np.zeros(N)

    # --- Define Constraints ---
    # Equality constraints from the consensus graph
    def constraint_consensus_boundary(z):
        c, r = z_to_pack(z)
        constraints = []
        wall_map_rev = {'xmin': 0, 'xmax': 1, 'ymin': 2, 'ymax': 3}
        for circle_idx_str, wall_kind in consensus_boundary:
            circle_idx = int(circle_idx_str)
            if wall_kind == 'xmin': constraints.append(c[circle_idx,0] - r[circle_idx])
            elif wall_kind == 'xmax': constraints.append(1 - c[circle_idx,0] - r[circle_idx])
            elif wall_kind == 'ymin': constraints.append(c[circle_idx,1] - r[circle_idx])
            elif wall_kind == 'ymax': constraints.append(1 - c[circle_idx,1] - r[circle_idx])
        return np.array(constraints)

    def constraint_consensus_pairs(z):
        c, r = z_to_pack(z)
        constraints = []
        for i, j in consensus_pairs:
            dist = np.linalg.norm(c[i] - c[j])
            constraints.append(dist - (r[i] + r[j]))
        return np.array(constraints)

    # Inequality constraints for all other possible contacts
    all_pairs = set(tuple(sorted((i,j))) for i in range(N) for j in range(i + 1, N))
    variable_pairs = all_pairs - set(map(tuple, consensus_pairs))
    def constraint_variable_pairs(z):
        c, r = z_to_pack(z)
        constraints = []
        for i, j in variable_pairs:
            dist = np.linalg.norm(c[i] - c[j])
            constraints.append(dist - (r[i] + r[j]))
        return np.array(constraints)

    # Load my SOTA solution as the starting seed
    try:
        z0 = pack_to_z(np.loadtxt("storage/Aletheia/sota_2_centers.txt"), np.loadtxt("storage/Aletheia/sota_2_radii.txt"))
    except IOError:
        return np.zeros((N,2)), np.zeros(N)

    constraints = [
        {'type': 'eq', 'fun': constraint_consensus_boundary},
        {'type': 'eq', 'fun': constraint_consensus_pairs},
        {'type': 'ineq', 'fun': constraint_variable_pairs}
    ]

    bounds = [(0,1) if i%3!=2 else (1e-6,0.5) for i in range(N*3)]

    res = minimize(objective, z0, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter':500, 'ftol':1e-10})

    final_centers, final_radii = z_to_pack(res.x)
    return final_centers, final_radii * (1.0 - 1e-9)
